// One-off script: backfills created_date/pay_date on Payslip rows that were
// generated by the live Payroll module before that fix shipped (both columns
// were always NULL -- see app/api/hr/payroll/route.ts's payslipRows mapping).
// Joins through PayrollRun to recover a reasonable date for each payslip.
// Only fills rows where the column is currently NULL -- never overwrites a
// real value (e.g. on payslips that came from the legacy data import, which
// already have these set).
//
// Usage: node scripts/backfill-payslip-dates.js
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  const payslips = await prisma.payslip.findMany({
    where: { OR: [{ created_date: null }, { pay_date: null }] },
    select: { id: true, payroll_run_id: true, created_date: true, pay_date: true },
  });

  if (!payslips.length) {
    console.log('No payslips need backfilling.');
    return;
  }

  const runIds = Array.from(new Set(payslips.map((p) => p.payroll_run_id).filter(Boolean)));
  const runs = await prisma.payrollRun.findMany({
    where: { id: { in: runIds } },
    select: { id: true, runDate: true, periodEnd: true },
  });
  const runById = new Map(runs.map((r) => [r.id, r]));

  let updated = 0;
  let skipped = 0;
  for (const p of payslips) {
    const run = p.payroll_run_id ? runById.get(p.payroll_run_id) : null;
    if (!run) { skipped++; continue; }

    const data = {};
    if (!p.created_date) data.created_date = run.runDate.toISOString();
    if (!p.pay_date) data.pay_date = run.periodEnd.toISOString().split('T')[0];

    if (Object.keys(data).length) {
      await prisma.payslip.update({ where: { id: p.id }, data });
      updated++;
    }
  }

  console.log(`Backfilled ${updated} payslip(s). Skipped ${skipped} (no matching payroll run).`);
}

main()
  .catch((err) => { console.error(err); process.exit(1); })
  .finally(() => prisma.$disconnect());
